// Generates the CLI and configuration reference fragments that the documentation site includes, from the built
// CLI program (packages/cli/dist) and schemas/config.json. Run `pnpm build` first. The output is formatted with the
// repository's Biome, so `pnpm lint` and `pnpm format` leave the generated files unchanged.
//
//   node scripts/docs-reference.mjs           write docs/reference/_generated/{cli,configuration}.md
//   node scripts/docs-reference.mjs --check   exit 1 when the files on disk differ from what would be written
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outDir = path.join(repo, 'docs', 'reference', '_generated');
const HEADER =
  '<!-- Generated by `node scripts/docs-reference.mjs` from the CLI and schemas/config.json. Do not edit; run the script instead. -->\n';
/** Integers up to this bound are "unbounded" for documentation purposes (zod's int() adds it). */
const MAX_SAFE = Number.MAX_SAFE_INTEGER;

/** Text for a Markdown table cell: escape pipes and characters VitePress would read as HTML or Vue syntax. */
function cell(text) {
  return String(text)
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\{\{/g, '&#123;&#123;')
    .replace(/\r?\n/g, ' ');
}

/** Inline code for a table cell. Only the pipe needs escaping inside a code span of a table. */
function code(text) {
  const value = String(text).replace(/\|/g, '\\|');
  const fence = value.includes('`') ? '``' : '`';

  return `${fence}${value}${fence}`;
}

/** Plain prose with inline code spans kept as written and other text escaped. */
function prose(text) {
  return String(text)
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 === 1 ? part.replace(/\|/g, '\\|') : cell(part)))
    .join('');
}

function table(header, rows) {
  const line = (cells) => `| ${cells.join(' | ')} |`;

  return [line(header), line(header.map(() => '---')), ...rows.map(line)].join('\n');
}

// ---------------------------------------------------------------------------------------------------------------
// CLI

function optionDefault(option) {
  if (option.defaultValueDescription) return cell(option.defaultValueDescription);

  if (option.defaultValue === undefined) return '';

  // `--root` defaults to the working directory of the process; never print the machine's path.
  if (option.defaultValue === process.cwd()) return 'current directory';

  return code(
    typeof option.defaultValue === 'string' ? option.defaultValue : JSON.stringify(option.defaultValue),
  );
}

function optionsTable(options) {
  const rows = options.map((option) => [
    code(option.flags),
    option.description ? prose(option.description) : '',
    option.argChoices ? option.argChoices.map(code).join(', ') : '',
    option.mandatory ? '**required**' : optionDefault(option),
  ]);

  return table(['Option', 'Description', 'Values', 'Default'], rows);
}

function argumentLabel(argument) {
  const name = `${argument.name()}${argument.variadic ? '...' : ''}`;

  return argument.required ? `<${name}>` : `[${name}]`;
}

function usage(names, command) {
  return [
    ...names,
    ...command.registeredArguments.map(argumentLabel),
    ...(command.options.length > 0 ? ['[options]'] : []),
    ...(command.commands.length > 0 ? ['<command>'] : []),
  ].join(' ');
}

function commandSection(names, command, depth) {
  const parts = [`${'#'.repeat(depth)} \`${names.join(' ')}\``, ''];

  if (command.description()) parts.push(prose(command.description()), '');
  parts.push('```text', usage(names, command), '```', '');

  if (command.registeredArguments.length > 0) {
    parts.push(
      table(
        ['Argument', 'Required', 'Description'],
        command.registeredArguments.map((argument) => [
          code(argumentLabel(argument)),
          argument.required ? 'yes' : 'no',
          argument.description ? prose(argument.description) : '',
        ]),
      ),
      '',
    );
  }

  if (command.options.length > 0) parts.push(optionsTable(command.options), '');

  if (command.commands.length > 0) {
    parts.push(
      table(
        ['Subcommand', 'Description'],
        command.commands.map((child) => [
          code([...names, child.name()].join(' ')),
          child.description() ? prose(child.description()) : '',
        ]),
      ),
      '',
    );
  }

  for (const child of command.commands)
    parts.push(commandSection([...names, child.name()], child, depth + 1));

  return parts.join('\n');
}

async function cliReference() {
  const dist = path.join(repo, 'packages', 'cli', 'dist', 'program.js');

  if (!existsSync(dist)) throw new Error(`${path.relative(repo, dist)} is missing; run \`pnpm build\` first`);
  const { buildProgram } = await import(pathToFileURL(dist).href);
  const program = buildProgram(
    () => {},
    () => {},
  );
  const parts = [
    HEADER,
    '## Global options',
    '',
    'These options belong to `veritas` itself and apply to every command. Put them before or after the command name.',
    '',
    optionsTable(program.options),
    '',
    '## Commands',
    '',
    table(
      ['Command', 'Description'],
      program.commands.map((command) => [
        code(`veritas ${command.name()}`),
        command.description() ? prose(command.description()) : '',
      ]),
    ),
    '',
  ];

  for (const command of program.commands) parts.push(commandSection(['veritas', command.name()], command, 3));

  return `${parts
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trimEnd()}\n`;
}

// ---------------------------------------------------------------------------------------------------------------
// Configuration

function json(value) {
  return JSON.stringify(value);
}

function typeOf(node) {
  if (node.const !== undefined) return `${Array.isArray(node.type) ? node.type.join(' or ') : node.type}`;

  if (node.type === 'array') {
    const items = node.items ?? {};
    const inner = items.type ?? 'value';

    return `array of ${inner}${node.minItems ? ` (at least ${node.minItems})` : ''}`;
  }

  return Array.isArray(node.type) ? node.type.join(' or ') : (node.type ?? 'value');
}

function bounds(node) {
  const lower =
    node.exclusiveMinimum !== undefined
      ? `> ${node.exclusiveMinimum}`
      : node.minimum !== undefined && node.minimum > -MAX_SAFE
        ? `>= ${node.minimum}`
        : '';
  const upper = node.maximum !== undefined && node.maximum < MAX_SAFE ? `<= ${node.maximum}` : '';

  return [lower, upper].filter(Boolean).join(', ');
}

function allowed(node) {
  if (node.const !== undefined) return `only ${code(json(node.const))} (fixed)`;

  if (node.enum) return node.enum.map((value) => code(value)).join(', ');

  if (node.type === 'array' && node.items?.enum)
    return node.items.enum.map((value) => code(value)).join(', ');

  if (node.type === 'array' && node.items?.pattern) return `items match ${code(node.items.pattern)}`;

  if (node.pattern) return `matches ${code(node.pattern)}`;

  return bounds(node);
}

function defaultCell(value) {
  return value === undefined ? 'unset' : code(json(value));
}

/** Rows for every leaf setting below `node`; an object's default supplies defaults its fields do not declare. */
function leaves(node, key, inherited, rows) {
  const own = node.default !== undefined ? node.default : inherited;

  if (node.type === 'object' && node.properties) {
    for (const [name, child] of Object.entries(node.properties)) {
      leaves(child, `${key}.${name}`, own && typeof own === 'object' ? own[name] : undefined, rows);
    }

    return;
  }
  rows.push({
    key,
    type: typeOf(node),
    default: own,
    allowed: allowed(node),
    description: node.description ?? '',
  });
}

function settingsTable(rows) {
  const withDescriptions = rows.some((row) => row.description);
  const header = [
    'Setting',
    'Type',
    'Default',
    'Allowed values',
    ...(withDescriptions ? ['Description'] : []),
  ];

  return table(
    header,
    rows.map((row) => [
      code(row.key),
      row.type,
      defaultCell(row.default),
      row.allowed,
      ...(withDescriptions ? [prose(row.description)] : []),
    ]),
  );
}

function configurationReference() {
  const schema = JSON.parse(readFileSync(path.join(repo, 'schemas', 'config.json'), 'utf8'));
  const top = [];
  const groups = [];

  for (const [name, node] of Object.entries(schema.properties)) {
    if (node.type === 'object' && node.properties) groups.push([name, node]);
    else top.push({ name, node });
  }
  const parts = [
    HEADER,
    'Every setting, with its type, default and allowed values, as validated by `schemas/config.json`. A setting',
    'whose allowed value is marked *fixed* accepts only that value. *unset* means the setting has no default value.',
    'Unknown keys are rejected.',
    '',
    '### Top level',
    '',
    settingsTable(
      top.map(({ name, node }) => ({
        key: name,
        type: typeOf(node),
        default: node.default,
        allowed: allowed(node),
        description: node.description ?? '',
      })),
    ),
    '',
  ];

  for (const [name, node] of groups) {
    const rows = [];
    leaves(node, name, undefined, rows);
    parts.push(`### \`${name}\``, '', settingsTable(rows), '');
  }

  return `${parts.join('\n').trimEnd()}\n`;
}

// ---------------------------------------------------------------------------------------------------------------

/** Format Markdown exactly as `biome format` does for a file at `file`. */
function biome(file, content) {
  const bin = path.join(repo, 'node_modules', '@biomejs', 'biome', 'bin', 'biome');
  const result = spawnSync(process.execPath, [bin, 'format', `--stdin-file-path=${file}`], {
    cwd: repo,
    input: content,
    encoding: 'utf8',
  });

  if (result.status !== 0) throw new Error(`biome format failed for ${file}:\n${result.stderr}`);

  return result.stdout;
}

const files = {
  'cli.md': biome('docs/reference/_generated/cli.md', await cliReference()),
  'configuration.md': biome('docs/reference/_generated/configuration.md', configurationReference()),
};

if (process.argv.includes('--check')) {
  const stale = Object.entries(files)
    .filter(([name, content]) => {
      const file = path.join(outDir, name);

      return !existsSync(file) || readFileSync(file, 'utf8') !== content;
    })
    .map(([name]) => path.relative(repo, path.join(outDir, name)));

  if (stale.length > 0) {
    process.stderr.write(
      `out of date: ${stale.join(', ')}\nrun \`pnpm build && node scripts/docs-reference.mjs\` and commit the result\n`,
    );
    process.exit(1);
  }
  process.stdout.write('docs reference is up to date\n');
} else {
  mkdirSync(outDir, { recursive: true });

  for (const [name, content] of Object.entries(files)) writeFileSync(path.join(outDir, name), content);
  process.stdout.write(`wrote ${Object.keys(files).length} files to ${path.relative(repo, outDir)}\n`);
}
